// Get input data from previous node
const rawData = $input.item.json.output || $input.item.json;

const is = rawData.income_statement || {};
const bs = rawData.balance_sheet || {};
const cf = rawData.cash_flow || {};

// Helper: Safe Percentage Calculation
function calcPctChange(current, prior) {
  if (prior === null || prior === 0 || prior === undefined || current === null || current === undefined) {
    return null;
  }
  return Number((((current - prior) / Math.abs(prior)) * 100).toFixed(2));
}

// Helper: Safe Division / Ratio Calculation
function calcRatio(numerator, denominator) {
  if (denominator === null || denominator === 0 || denominator === undefined || numerator === null || numerator === undefined) {
    return null;
  }
  return Number((numerator / denominator).toFixed(2));
}

// Helper: Safe Margin Calculation (%)
function calcMargin(part, whole) {
  if (whole === null || whole === 0 || whole === undefined || part === null || part === undefined) {
    return null;
  }
  return Number(((part / whole) * 100).toFixed(2));
}

// 1. Growth & Change Metrics
const growth = {
  revenue_growth_pct: calcPctChange(is.revenue?.current, is.revenue?.prior),
  gross_profit_growth_pct: calcPctChange(is.gross_profit?.current, is.gross_profit?.prior),
  operating_income_growth_pct: calcPctChange(is.operating_income?.current, is.operating_income?.prior),
  net_income_growth_pct: calcPctChange(is.net_income?.current, is.net_income?.prior),
  cash_change_pct: calcPctChange(bs.cash_and_equivalents?.current, bs.cash_and_equivalents?.prior),
  debt_change_pct: calcPctChange(bs.total_debt?.current, bs.total_debt?.prior),
  operating_cash_flow_growth_pct: calcPctChange(cf.operating_cash_flow?.current, cf.operating_cash_flow?.prior)
};

// 2. Financial Ratios (Current Period)
const ratios_current = {
  // Profitability Ratios (%)
  gross_margin_pct: calcMargin(is.gross_profit?.current, is.revenue?.current),
  operating_margin_pct: calcMargin(is.operating_income?.current, is.revenue?.current),
  net_margin_pct: calcMargin(is.net_income?.current, is.revenue?.current),

  // Liquidity Ratios
  current_ratio: calcRatio(bs.current_assets?.current, bs.current_liabilities?.current),
  cash_ratio: calcRatio(bs.cash_and_equivalents?.current, bs.current_liabilities?.current),

  // Leverage Ratios
  debt_to_equity: calcRatio(bs.total_debt?.current, bs.total_equity?.current),
  debt_to_assets: calcRatio(bs.total_debt?.current, bs.total_assets?.current),

  // Efficiency Ratio
  asset_turnover: calcRatio(is.revenue?.current, bs.total_assets?.current)
};

// 3. Financial Ratios (Prior Period)
const ratios_prior = {
  gross_margin_pct: calcMargin(is.gross_profit?.prior, is.revenue?.prior),
  operating_margin_pct: calcMargin(is.operating_income?.prior, is.revenue?.prior),
  net_margin_pct: calcMargin(is.net_income?.prior, is.revenue?.prior),
  current_ratio: calcRatio(bs.current_assets?.prior, bs.current_liabilities?.prior),
  cash_ratio: calcRatio(bs.cash_and_equivalents?.prior, bs.current_liabilities?.prior),
  debt_to_equity: calcRatio(bs.total_debt?.prior, bs.total_equity?.prior),
  debt_to_assets: calcRatio(bs.total_debt?.prior, bs.total_assets?.prior),
  asset_turnover: calcRatio(is.revenue?.prior, bs.total_assets?.prior)
};

// 4. Margin Shifts (Basis Points / Direct % Point Difference)
const ratio_changes = {
  gross_margin_shift: (ratios_current.gross_margin_pct !== null && ratios_prior.gross_margin_pct !== null) 
    ? Number((ratios_current.gross_margin_pct - ratios_prior.gross_margin_pct).toFixed(2)) : null,
  operating_margin_shift: (ratios_current.operating_margin_pct !== null && ratios_prior.operating_margin_pct !== null) 
    ? Number((ratios_current.operating_margin_pct - ratios_prior.operating_margin_pct).toFixed(2)) : null,
  net_margin_shift: (ratios_current.net_margin_pct !== null && ratios_prior.net_margin_pct !== null) 
    ? Number((ratios_current.net_margin_pct - ratios_prior.net_margin_pct).toFixed(2)) : null
};

// Return Final Structured Model
return {
  json: {
    meta: {
      company_name: rawData.company_name,
      report_period: rawData.report_period,
      currency: rawData.currency
    },
    raw_financials: rawData,
    calculated_growth: growth,
    ratios: {
      current_period: ratios_current,
      prior_period: ratios_prior,
      margin_shifts: ratio_changes
    }
  }
};

// 1. Get Financial Data
const financialData = $('Trend & Risk Engine').first().json;

// 2. Get AI Agent output
const aiInput = $input.item.json;

let aiResponse = 
  aiInput.output || 
  aiInput.text || 
  aiInput.message?.content || 
  (typeof aiInput === 'string' ? aiInput : "AI Commentary unavailable.");

// Clean up AI Response Formatting for Telegram HTML
let formattedAiResponse = aiResponse
  .replace(/### (.*)/g, '\n<b>🔸 $1</b>')
  .replace(/## (.*)/g, '\n<b>🔹 $1</b>')
  .replace(/\*\*(.*?)\*\*/g, '<b>$1</b>')
  .replace(/^- (.*)/gm, '  • $1')                   // Format bullets neatly
  .replace(/\n{3,}/g, '\n\n')                       // Remove excessive line breaks
  .trim();

// 3. Extracted Financial Metrics
const meta = financialData.meta || {};
const raw = financialData.raw_financials || {};
const is = raw.income_statement || {};
const bs = raw.balance_sheet || {};
const cf = raw.cash_flow || {};
const growth = financialData.calculated_growth || {};
const ratios = financialData.ratios?.current_period || {};
const risk = financialData.risk_engine || {};

// ----------------------------------------------------
// STRICT FORMATTING HELPERS
// ----------------------------------------------------
const isValid = (val) => val !== null && val !== undefined && !isNaN(val) && typeof val === 'number';

// Money: Output '$75.0M' if valid, strictly 'N/A' (without $) if invalid
const fmtMoney = (val) => isValid(val) ? `$${(val / 1e6).toFixed(1)}M` : 'N/A';

// Growth: Output ' (<code>+7.14%</code>)' if valid, strictly EMPTY STRING "" if invalid (Prevents +null% bug)
const fmtGrowth = (val) => isValid(val) ? ` (<code>${val >= 0 ? '+' : ''}${val}%</code>)` : '';

// Ratio & Percentage Helpers (Prevents N/Ax and N/A% bug)
const fmtPct = (val) => isValid(val) ? `<code>${val}%</code>` : '<code>N/A</code>';
const fmtRatio = (val) => isValid(val) ? `<code>${val}x</code>` : '<code>N/A</code>';

// Risk Emoji
const riskEmoji = risk.overall_risk_level === 'High' ? '🔴' : risk.overall_risk_level === 'Medium' ? '🟡' : '🟢';

// Deterministic Risk Drivers List (Fallback to "• None identified")
const riskDriversList = (Array.isArray(risk.risk_drivers) && risk.risk_drivers.length > 0)
  ? risk.risk_drivers.map(r => `• ${r}`).join('\n')
  : '• None identified';

// ----------------------------------------------------
// 4. Assemble Telegram Message
// ----------------------------------------------------
const telegramHTML = `
📊 <b>EXECUTIVE FINANCIAL BRIEF</b>
━━━━━━━━━━━━━━━━━━━━━━━━━━
🏢 <b>Company:</b> ${meta.company_name || 'N/A'}
📅 <b>Period:</b> ${meta.report_period || 'N/A'} (${meta.currency || 'USD'})
⚠️ <b>Health:</b> ${riskEmoji} <b>${risk.overall_risk_level || 'N/A'} Risk Level</b>

📈 <b>KEY FINANCIAL METRICS</b>
• <b>Revenue:</b> ${fmtMoney(is.revenue?.current)}${fmtGrowth(growth.revenue_growth_pct)}
• <b>Net Income:</b> ${fmtMoney(is.net_income?.current)}${fmtGrowth(growth.net_income_growth_pct)}
• <b>Net Margin:</b> ${fmtPct(ratios.net_margin_pct ?? ratios.net_margin)}
• <b>Op. Cash Flow:</b> ${fmtMoney(cf.operating_cash_flow?.current)}${fmtGrowth(growth.operating_cash_flow_growth_pct)}
• <b>Total Debt:</b> ${fmtMoney(bs.total_debt?.current)}${fmtGrowth(growth.debt_change_pct)}
• <b>Debt / Equity:</b> ${fmtRatio(ratios.debt_to_equity)}
• <b>Current Ratio:</b> ${fmtRatio(ratios.current_ratio)}

🚨 <b>DETERMINISTIC RISK DRIVERS</b>
${riskDriversList}

━━━━━━━━━━━━━━━━━━━━━━━━━━
🤖 <b>AI ANALYST COMMENTARY</b>
${formattedAiResponse}
`.trim();

return {
  json: {
    telegram_html: telegramHTML
  }
};

const data = $input.item.json;
const growth = data.calculated_growth || {};
const ratiosCurrent = data.ratios?.current_period || {};
const shifts = data.ratios?.margin_shifts || {};
const rawCF = data.raw_financials?.cash_flow || {};

// Helper: Check valid numeric value (Excludes null, undefined, NaN)
const isValid = (val) => val !== null && val !== undefined && !isNaN(val) && typeof val === 'number';

// Helper: Safe Absolute Extraction
const getAbsValue = (val) => isValid(val) ? Math.abs(val) : null;

// ----------------------------------------------------
// 0. DETERMINISTIC CAPEX & FCF CALCULATIONS
// ----------------------------------------------------
// IMPORTANT:
// FCF = Operating Cash Flow - Capital Expenditure
//
// Do NOT use Investing Cash Flow as CapEx.
// Investing Cash Flow may contain acquisitions,
// investments, asset sales, or other investing activity.
//
// Do NOT trust AI-generated/raw FCF when OCF + CapEx
// are available. Calculate FCF deterministically.

const ocfCurrent = isValid(rawCF.operating_cash_flow?.current)
  ? rawCF.operating_cash_flow.current
  : null;

const ocfPrior = isValid(rawCF.operating_cash_flow?.prior)
  ? rawCF.operating_cash_flow.prior
  : null;

// ----------------------------------------------------
// CAPEX
// ----------------------------------------------------
let capexCurrent = null;
if (isValid(rawCF.capital_expenditure?.current)) {
  capexCurrent = getAbsValue(rawCF.capital_expenditure.current);
} else if (isValid(rawCF.capex?.current)) {
  capexCurrent = getAbsValue(rawCF.capex.current);
}

let capexPrior = null;
if (isValid(rawCF.capital_expenditure?.prior)) {
  capexPrior = getAbsValue(rawCF.capital_expenditure.prior);
} else if (isValid(rawCF.capex?.prior)) {
  capexPrior = getAbsValue(rawCF.capex.prior);
}

// ----------------------------------------------------
// FREE CASH FLOW
// ----------------------------------------------------
let fcfCurrent = null;
if (ocfCurrent !== null && capexCurrent !== null) {
  fcfCurrent = ocfCurrent - capexCurrent;
}

let fcfPrior = null;
if (ocfPrior !== null && capexPrior !== null) {
  fcfPrior = ocfPrior - capexPrior;
}

// ----------------------------------------------------
// FCF GROWTH
// ----------------------------------------------------
// Only calculate percentage growth when prior FCF is
// a valid non-zero number.
//
// If prior FCF is zero or unavailable, return N/A
// instead of generating misleading percentages.

let fcfGrowthPct = null;
if (
  fcfCurrent !== null &&
  fcfPrior !== null &&
  fcfPrior !== 0
) {
  fcfGrowthPct = Number(
    (((fcfCurrent - fcfPrior) / Math.abs(fcfPrior)) * 100).toFixed(2)
  );
}

// ----------------------------------------------------
// UPDATED CASH FLOW
// ----------------------------------------------------
const updatedCashFlow = {
  ...rawCF,

  capital_expenditure: {
    current: capexCurrent,
    prior: capexPrior
  },

  free_cash_flow: {
    current: fcfCurrent,
    prior: fcfPrior
  }
};

// ----------------------------------------------------
// UPDATED GROWTH
// ----------------------------------------------------
const updatedGrowth = {
  ...growth,
  free_cash_flow_growth_pct: fcfGrowthPct
};

// ----------------------------------------------------
// 1. Trend Evaluation
// ----------------------------------------------------
const trends = {
  revenue_trend: isValid(updatedGrowth.revenue_growth_pct) ? (updatedGrowth.revenue_growth_pct > 0 ? "Positive" : (updatedGrowth.revenue_growth_pct < 0 ? "Negative" : "Flat")) : "N/A",
  profitability_trend: isValid(updatedGrowth.net_income_growth_pct) ? (updatedGrowth.net_income_growth_pct > 0 && (shifts.net_margin_shift ?? 0) >= 0 ? "Positive" : (updatedGrowth.net_income_growth_pct < 0 ? "Negative" : "Mixed/Caution")) : "N/A",
  cash_flow_trend: (fcfGrowthPct !== null && fcfGrowthPct >= 0) || (isValid(updatedGrowth.operating_cash_flow_growth_pct) && updatedGrowth.operating_cash_flow_growth_pct >= 0) ? "Positive" : "Negative",
  leverage_trend: (isValid(updatedGrowth.debt_change_pct) && updatedGrowth.debt_change_pct > 15) || (isValid(ratiosCurrent.debt_to_equity) && ratiosCurrent.debt_to_equity > 1.2) ? "Caution" : "Stable",
  liquidity_trend: isValid(ratiosCurrent.current_ratio) ? (ratiosCurrent.current_ratio < 1.0 ? "High Risk" : (ratiosCurrent.current_ratio < 1.5 ? "Caution" : "Healthy")) : "N/A"
};

// ----------------------------------------------------
// 2. Risk Drivers Engine (Rules-based Detection)
// ----------------------------------------------------
const riskDrivers = [];

// Leverage / Debt Rules
if (isValid(updatedGrowth.debt_change_pct) && updatedGrowth.debt_change_pct > 20) {
  riskDrivers.push(`Total Debt increased significantly (+${updatedGrowth.debt_change_pct}%)`);
}
if (isValid(ratiosCurrent.debt_to_equity) && ratiosCurrent.debt_to_equity > 1.5) {
  riskDrivers.push(`High Debt-to-Equity ratio (${ratiosCurrent.debt_to_equity}x)`);
}

// Cash Flow & Liquidity Rules
if (isValid(updatedGrowth.operating_cash_flow_growth_pct) && updatedGrowth.operating_cash_flow_growth_pct < 0) {
  const isGrowing = (isValid(updatedGrowth.revenue_growth_pct) && updatedGrowth.revenue_growth_pct > 0) || (isValid(updatedGrowth.net_income_growth_pct) && updatedGrowth.net_income_growth_pct > 0);
  const tailText = isGrowing ? " despite revenue/profit growth" : "";
  riskDrivers.push(`Operating Cash Flow declined (${updatedGrowth.operating_cash_flow_growth_pct}%)${tailText}`);
}
if (isValid(fcfGrowthPct) && fcfGrowthPct < 0 && fcfCurrent !== null) {
  riskDrivers.push(`Free Cash Flow declined (${fcfGrowthPct}%) to $${(fcfCurrent / 1e6).toFixed(1)}M due to heavy CapEx/operating pressures`);
}
if (isValid(updatedGrowth.cash_change_pct) && updatedGrowth.cash_change_pct < -15) {
  riskDrivers.push(`Cash reserves depleted significantly (${updatedGrowth.cash_change_pct}%)`);
}

// Current Ratio Rule (Strict Check: Only trigger if valid number exists)
if (isValid(ratiosCurrent.current_ratio) && ratiosCurrent.current_ratio < 1.2) {
  riskDrivers.push(`Current Ratio is tight (${ratiosCurrent.current_ratio}x)`);
}

// Profitability / Margin Rules
if (isValid(shifts.net_margin_shift) && shifts.net_margin_shift < -1.0) {
  riskDrivers.push(`Net Margin compressed by ${Math.abs(shifts.net_margin_shift)} percentage points`);
}
if (isValid(shifts.gross_margin_shift) && shifts.gross_margin_shift < -2.0) {
  riskDrivers.push(`Gross Margin declined by ${Math.abs(shifts.gross_margin_shift)} percentage points`);
}

// ----------------------------------------------------
// 3. Overall Risk Level Assignment
// ----------------------------------------------------
let overallRisk = "Low";
if (
  riskDrivers.length >= 3 || 
  (isValid(ratiosCurrent.debt_to_equity) && ratiosCurrent.debt_to_equity > 2.0) || 
  (isValid(ratiosCurrent.current_ratio) && ratiosCurrent.current_ratio < 1.0)
) {
  overallRisk = "High";
} else if (riskDrivers.length >= 1) {
  overallRisk = "Medium";
}

return {
  json: {
    ...data,
    raw_financials: {
      ...data.raw_financials,
      cash_flow: updatedCashFlow
    },
    calculated_growth: updatedGrowth,
    trends: trends,
    risk_engine: {
      overall_risk_level: overallRisk,
      risk_driver_count: riskDrivers.length,
      risk_drivers: riskDrivers
    }
  }
};
